import type {ReactNode} from 'react'
import Link from 'next/link'
import {ArrowRight,Layers3} from 'lucide-react'
import {BrandLogo} from './brand-logo'

/**
 * Read-only, public-facing shell for links shared outside Coollects.
 * No authenticated app navigation or account-management controls.
 * The return path is generated by the page, not supplied as a raw redirect.
 */
export function GuestSharedShell({children,returnTo}:{children:ReactNode;returnTo:string}){
 const register='/registrar?next='+encodeURIComponent(returnTo)
 const login='/entrar?next='+encodeURIComponent(returnTo)
 return <main className="app-frame guest-shared-shell">
  <header className="topbar guest-shared-header">
   <Link className="screen-logo" href="/" aria-label="Coollects — início"><BrandLogo/></Link>
   <Link className="guest-shared-login" href={login}>Entrar</Link>
  </header>
  <div className="screen-body screen-body-compact guest-shared-content">
   {children}
   <aside className="guest-join-panel" aria-labelledby="guest-join-title">
    <div className="guest-join-icon" aria-hidden="true"><Layers3 size={25}/></div>
    <p className="guest-join-eyebrow">SEU UNIVERSO DE COLEÇÕES</p>
    <h2 id="guest-join-title">Gostou de explorar? Crie sua própria coleção.</h2>
    <p>Guarde seus itens, organize suas descobertas e compartilhe suas histórias com quem gosta das mesmas coisas.</p>
    <Link className="guest-join-primary" href={register}>Criar minha conta grátis <ArrowRight size={18}/></Link>
    <p className="guest-join-existing">Já coleciona com a gente? <Link href={login}>Entrar na minha conta</Link></p>
   </aside>
  </div>
 </main>
}
